T={(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)}
pts={'2':{(3,13),(4,12),(5,11)},'8':{(1,23),(2,23),(3,22)},'5':{(9,25),(10,24),(10,25)},'6':{(11,5),(12,5),(12,7)},'3':{(11,15),(12,16),(13,16)},'7':{(19,11),(20,12)},'9':{(22,5),(23,3)}}
def transforms(S):
 out=[]
 for k in range(4):
  for refl in (False,True):
   q=set()
   for r,c in S:
    if refl:c=-c
    for _ in range(k):r,c=c,-r
    q.add((r,c))
   mr=min(r for r,c in q); mc=min(c for r,c in q)
   out.append({(r-mr,c-mc) for r,c in q})
 return list(dict.fromkeys(tuple(sorted(x)) for x in out))
Ts=[set(x) for x in transforms(T)]
for col,P in pts.items():
 sols=[]
 for t in Ts:
  for p in P:
   for a in t:
    dr,dc=p[0]-a[0],p[1]-a[1]
    if all((x+dr,y+dc) in {(r,c) for r in range(30) for c in range(30)} for x,y in t) and P <= {(x+dr,y+dc) for x,y in t}:
     sols.append((t,dr,dc))
 sols=list(dict.fromkeys((tuple(sorted(t)),dr,dc) for t,dr,dc in sols))
 print(col,len(sols),[(dr,dc) for _,dr,dc in sols[:8]])

# generate candidate forms and use first unique fit by transform ordering
arr=[[1]*30 for _ in range(30)]
# template itself keep as is
for r,c in T: arr[r+3][c+5]=4
for col,P in pts.items():
 candidates=[]
 for ti,t in enumerate(Ts):
  for p in sorted(P):
   for a in sorted(t):
    dr,dc=p[0]-a[0],p[1]-a[1]
    moved={(x+dr,y+dc) for x,y in t}
    if P<=moved and min(x for x,y in moved)>=0 and max(x for x,y in moved)<30 and min(y for x,y in moved)>=0 and max(y for x,y in moved)<30:
     candidates.append((ti,dr,dc,moved))
 # unique moved sets, choose first
 unique=[]
 for x in candidates:
  if not any(x[3]==u[3] for u in unique): unique.append(x)
 chosen=unique[0]
 for r,c in chosen[3]:arr[r][c]=int(col)
 print(col, chosen[:3], sorted(chosen[3]))
print('\n'.join(' '.join(map(str,row)) for row in arr))

for col,P in pts.items():
 cand={}
 for ti,t in enumerate(Ts):
  for p in P:
   for a in t:
    dr,dc=p[0]-a[0],p[1]-a[1]; moved={(x+dr,y+dc) for x,y in t}
    if P<=moved and min(x for x,y in moved)>=0 and max(x for x,y in moved)<30 and min(y for x,y in moved)>=0 and max(y for x,y in moved)<30:
     cand[tuple(sorted(moved))]=moved
 pc=(sum(r for r,c in P)/len(P),sum(c for r,c in P)/len(P))
 ranked=sorted(cand.values(),key=lambda m: ((sum(r for r,c in m)/6-pc[0])**2+(sum(c for r,c in m)/6-pc[1])**2))
 print(col,[(min(r for r,c in m),min(c for r,c in m),round(sum(r for r,c in m)/6,2),round(sum(c for r,c in m)/6,2)) for m in ranked])

# number candidates rotations only
Trot=[]
for k in range(4):
 q=set(T)
 for _ in range(k):q={(c,-r) for r,c in q}
 mr=min(r for r,c in q);mc=min(c for r,c in q); Trot.append({(r-mr,c-mc) for r,c in q})
for col,P in pts.items():
 sol=[]
 for i,t in enumerate(Trot):
  for p in P:
   for a in t:
    dr,dc=p[0]-a[0],p[1]-a[1];m={(r+dr,c+dc) for r,c in t}
    if P<=m:sol.append((i,dr,dc))
 print(col,sol[:10])
